import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv: empty invoices array', () => {
  const result = exportCsv([]);

  assert(result.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
  const lines = result.split('\n');
  assert.equal(lines.length, 2);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], '');
});

test('exportCsv: single issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[1].includes('Acme Corp'));
  assert(lines[1].includes('2026-10-07'));
  assert(lines[1].includes('issued'));
});

test('exportCsv: draft invoice has no number', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const result = exportCsv([inv.value]);

  const lines = result.split('\n');
  assert(lines[1].startsWith(','));
});

test('exportCsv: amounts formatted as euros', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const subtotal = parseFloat(fields[5]);
  assert(subtotal > 0);
  assert.equal(fields[5].includes('.'), true);
});

test('exportCsv: two decimal places', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[5], /\.\d{2}$/);
  assert.match(fields[8], /\.\d{2}$/);
});

test('exportCsv: no currency sign or thousands separator', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  assert(!result.includes('€'));
  assert(!result.includes(','));
});

test('exportCsv: customer name with comma is quoted', () => {
  const result = exportCsv([
    {
      number: 'INV-2026-0001',
      customerId: 'C-003',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 5, unitPrice: 9500, vatRate: 21, name: 'Dev Hour' }],
    },
  ]);

  const lines = result.split('\n');
  assert(lines[1].includes('"Kite & Co"'));
});

test('exportCsv: customer name with quotes is escaped', () => {
  const result = exportCsv([
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 5, unitPrice: 9500, vatRate: 21, name: 'Dev Hour' }],
    },
  ]);

  const lines = result.split('\n');
  assert(lines[1].includes('Acme Corp'));
});

test('exportCsv: multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv1.ok);
  const inv1Issue = issueInvoice(inv1.value, []);
  assert(inv1Issue.ok);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert(inv2.ok);
  const inv2Issue = issueInvoice(inv2.value, ['INV-2026-0001']);
  assert(inv2Issue.ok);

  const result = exportCsv([inv1Issue.value, inv2Issue.value]);

  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[2].includes('INV-2026-0002'));
});

test('exportCsv: order preserved', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv1.ok);
  const inv1Issue = issueInvoice(inv1.value, []);
  assert(inv1Issue.ok);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv2.ok);
  const inv2Issue = issueInvoice(inv2.value, ['INV-2026-0001']);
  assert(inv2Issue.ok);

  const result = exportCsv([inv1Issue.value, inv2Issue.value]);

  const lines = result.split('\n');
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[2].includes('INV-2026-0002'));
});

test('exportCsv: includes all required columns', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  const headers = lines[0].split(',');
  assert.deepEqual(headers, ['number', 'customer', 'issueDate', 'dueDate', 'status', 'subtotal', 'discount', 'vat', 'total', 'due']);

  const fields = lines[1].split(',');
  assert.equal(fields.length, 10);
});

test('exportCsv: draft invoice no dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const result = exportCsv([inv.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[3], '');
});

test('exportCsv: issued invoice has dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[3], '2026-11-06');
});

test('exportCsv: discount is calculated', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const discount = parseFloat(fields[6]);
  assert(discount > 0);
});

test('exportCsv: VAT is calculated', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const vat = parseFloat(fields[7]);
  assert(vat > 0);
});

test('exportCsv: due is calculated from balance', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const payment = recordPayment(invIssue.value, { amount: 30000, date: '2026-10-10' });
  assert(payment.ok);

  const result = exportCsv([payment.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const due = parseFloat(fields[9]);
  const total = parseFloat(fields[8]);
  assert(due < total);
});

test('exportCsv: ends with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  assert.equal(result[result.length - 1], '\n');
});

test('exportCsv: with voucher', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invWithVoucher = { ...inv.value, voucher: { code: 'SAVE10', amount: 10000 } };
  const invIssue = issueInvoice(invWithVoucher, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const total = parseFloat(fields[8]);
  assert(total > 0);
});

test('exportCsv: fully paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const total = invIssue.value.lines.reduce((sum, line) => {
    const lineAmount = line.qty * line.unitPrice;
    const lineDiscount = Math.round(lineAmount * (line.discountPercent || 0) / 100);
    const amountAfterDiscount = lineAmount - lineDiscount;
    const lineVAT = Math.round(amountAfterDiscount * line.vatRate / 100);
    return sum + lineAmount - lineDiscount + lineVAT;
  }, 0);

  const payment = recordPayment(invIssue.value, { amount: total, date: '2026-10-10' });
  assert(payment.ok);

  const result = exportCsv([payment.value]);

  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const due = parseFloat(fields[9]);
  assert.equal(due, 0.00);
});

test('exportCsv: status shows current state', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const payment = recordPayment(invIssue.value, { amount: 30000, date: '2026-10-10' });
  assert(payment.ok);

  const result = exportCsv([payment.value]);

  const lines = result.split('\n');
  assert(lines[1].includes('partially_paid'));
});

