test('exportCsv: no currency sign or thousands separator in amounts', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const result = exportCsv([invIssue.value]);

  assert(!result.includes('€'));
  const lines = result.split('\n');
  const headerFields = lines[0].split(',');
  const amountFields = lines[1].split(',');
  const subtotalIdx = headerFields.indexOf('subtotal');
  const subtotalAmount = amountFields[subtotalIdx];
  assert(!subtotalAmount.includes(','));
});

